    @SuppressWarnings("unchecked") private Map<String,Object> data(String response){return (Map<String,Object>)JsonUtils.readMap(response).get("data");}
    private String project()throws Exception {
        return String.valueOf(data(mvc.perform(post("/api/projects").contentType(MediaType.APPLICATION_JSON).content(JsonUtils.write(DraftBusinessRules.map("id","native-layout-"+UUID.randomUUID(),"nameZhHans","TEST ONLY 原生分页","nameEn","TEST ONLY native pagination")))).andExpect(jsonPath("$.code").value(0)).andReturn().getResponse().getContentAsString()).get("id"));
    }
    private byte[] source(String key)throws Exception{return Files.readAllBytes(Paths.get(System.getProperty("consense.acceptance.bindingSourceDir"),key+"-source.docx"));}
    private void upload(String id,String key,byte[] bytes)throws Exception {
        mvc.perform(multipart("/api/drafting/{id}/templates/{key}/replace",id,key).file(new MockMultipartFile("file",key+".docx","application/vnd.openxmlformats-officedocument.wordprocessingml.document",bytes))).andExpect(jsonPath("$.data.parsed").value(1));
    }
    private void evidence(String name,byte[] bytes)throws Exception{Files.createDirectories(EVIDENCE);Files.write(EVIDENCE.resolve(name),bytes);}
    @SuppressWarnings("unchecked") @Test void originalNttPreviewStartsEachRegisteredContinuationAfterThePreviousManualFooter()throws Exception {
        String id=project();byte[] original=source("NTT");upload(id,"NTT",original);
        Map<String,Object> sourceBundle=data(mvc.perform(get("/api/drafting/{id}/templates/NTT/bindings",id)).andExpect(jsonPath("$.code").value(0)).andReturn().getResponse().getContentAsString());
        byte[] pdf=mvc.perform(get("/api/drafting/{id}/templates/NTT/preview.pdf",id).param("sourceSha256",DraftPdfConverter.sha256(original))).andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PDF)).andReturn().getResponse().getContentAsByteArray();
        evidence("NTT-original.docx",original);evidence("NTT-source.pdf",pdf);evidence("NTT-source-bindings.json",JsonUtils.write(sourceBundle).getBytes(StandardCharsets.UTF_8));
        assertArrayEquals(original,mvc.perform(get("/api/drafting/{id}/templates/NTT/source",id)).andReturn().getResponse().getContentAsByteArray());
        assertNoFooterThenTitle(pdf,"NTT");assertNoBlankOrFurnitureOnly(pdf,"NTT");
        Map<String,Object> located=data(mvc.perform(get("/api/drafting/{id}/templates/NTT/bindings",id)).andExpect(jsonPath("$.data.geometryStatus").value("ready")).andReturn().getResponse().getContentAsString());Map<String,Object> body=((List<Map<String,Object>>)located.get("bindings")).stream().filter(b->Integer.valueOf(546).equals(b.get("sourceParagraphOrdinal"))).findFirst().get();assertNotNull(body.get("geometry"));DraftingDesktopPdfIntegrationTest.assertActualParagraphNear(pdf,body,"The tenderer's attention is drawn");evidence("NTT-located-source-bindings.json",JsonUtils.write(located).getBytes(StandardCharsets.UTF_8));
        @SuppressWarnings("unchecked") Map<String,Object> layout=(Map<String,Object>)sourceBundle.get("nativeLayout");assertEquals("applied",layout.get("status"));assertEquals(sourceBundle.get("docxSha256"),layout.get("docxSha256"));assertEquals(sourceBundle.get("sourceSha256"),layout.get("sourceSha256"));
    }
    @Test void aModifiedSourceEditionIsPreservedAndExplicitlySkipsTheVerifiedLayout()throws Exception {
        String id=project();byte[] original=source("NTT"),modified=modifiedSource(original);assertNotEquals(DraftPdfConverter.sha256(original),DraftPdfConverter.sha256(modified));upload(id,"NTT",modified);
        Map<String,Object> bundle=data(mvc.perform(get("/api/drafting/{id}/templates/NTT/bindings",id)).andExpect(jsonPath("$.data.nativeLayout.status").value("skipped_unverified_source")).andExpect(jsonPath("$.data.nativeLayout.actions").isEmpty()).andReturn().getResponse().getContentAsString());
        assertEquals(DraftPdfConverter.sha256(modified),bundle.get("sourceSha256"));assertArrayEquals(modified,mvc.perform(get("/api/drafting/{id}/templates/NTT/source",id)).andReturn().getResponse().getContentAsByteArray());
        evidence("NTT-modified-source.docx",modified);evidence("NTT-modified-source-bindings.json",JsonUtils.write(bundle).getBytes(StandardCharsets.UTF_8));
    }
