    @SuppressWarnings("unchecked")
    @Test void switchingToDesktopOnlyReportsAnUnrepairedSavedRevisionAndNeverRewritesItsHumanBody()throws Exception {
        String id=project();for(String key:Arrays.asList("NTT","SCT","SCC"))upload(id,key,source(key));String kind=properties.getDrafting().getRendererKind();
        try {
            properties.getDrafting().setRendererKind("libreoffice");Map<String,Object> legacy=generate(id,"NTT");byte[] originalWord=word(id,String.valueOf(legacy.get("revisionId")));assertNull(legacy.get("nativeLayout"));assertEquals(0,xml(originalWord).getElementsByTagNameNS("http://schemas.openxmlformats.org/wordprocessingml/2006/main","pageBreakBefore").getLength());
            Map<String,Object> body=((List<Map<String,Object>>)legacy.get("blocks")).stream().filter(b->Boolean.TRUE.equals(b.get("editable"))&&String.valueOf(b.get("text")).contains("The tenderer's attention is drawn")).findFirst().get();String human=body.get("text")+"\nTEST ONLY pre-policy human body.";
            Map<String,Object> saved=data(mvc.perform(put("/api/drafting/{id}/documents/NTT",id).contentType(MediaType.APPLICATION_JSON).content(JsonUtils.write(patch(legacy,body,human,null)))).andExpect(jsonPath("$.code").value(0)).andReturn().getResponse().getContentAsString());byte[] frozen=word(id,String.valueOf(saved.get("revisionId")));properties.getDrafting().setRendererKind("desktop-x2t");
            Map<String,Object> current=((List<Map<String,Object>>)JsonUtils.readMap(mvc.perform(get("/api/drafting/{id}/documents",id)).andExpect(jsonPath("$.code").value(0)).andReturn().getResponse().getContentAsString()).get("data")).stream().filter(d->"NTT".equals(d.get("fileKey"))).findFirst().get();
            Map<String,Object> layout=(Map<String,Object>)current.get("nativeLayout");assertEquals("not_applied_to_saved_revision",layout.get("status"));assertEquals(saved.get("revisionId"),current.get("revisionId"));assertEquals(saved.get("docxSha256"),current.get("docxSha256"));assertTrue(String.valueOf(current.get("content")).contains("TEST ONLY pre-policy human body."));assertArrayEquals(frozen,word(id,String.valueOf(saved.get("revisionId"))));
            Map<String,Object> bindings=data(mvc.perform(get("/api/drafting/{id}/documents/NTT/bindings",id)).andExpect(jsonPath("$.data.nativeLayout.status").value("not_applied_to_saved_revision")).andReturn().getResponse().getContentAsString());assertEquals(saved.get("docxSha256"),bindings.get("docxSha256"));
            byte[] pdf=mvc.perform(get("/api/drafting/{id}/documents/NTT/preview.pdf",id).param("revisionId",String.valueOf(saved.get("revisionId")))).andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_PDF)).andReturn().getResponse().getContentAsByteArray();assertArrayEquals(frozen,word(id,String.valueOf(saved.get("revisionId"))));assertEquals(0,xml(frozen).getElementsByTagNameNS("http://schemas.openxmlformats.org/wordprocessingml/2006/main","pageBreakBefore").getLength());
            evidence("NTT-frozen-unrepaired-human.docx",frozen);evidence("NTT-frozen-unrepaired-human.pdf",pdf);evidence("NTT-frozen-unrepaired-info.json",JsonUtils.write(current).getBytes(StandardCharsets.UTF_8));
        } finally {properties.getDrafting().setRendererKind(kind);}
    }
    private static byte[] modifiedSource(byte[] bytes)throws Exception {
        ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(bytes));ZipOutputStream zip=new ZipOutputStream(out)){ZipEntry entry;while((entry=in.getNextEntry())!=null){byte[] data=in.readAllBytes();if("word/document.xml".equals(entry.getName()))data=new String(data,StandardCharsets.UTF_8).replaceFirst("NOTES TO TENDERERS","NOTES TO TENDERERS TEST ONLY EDITION").getBytes(StandardCharsets.UTF_8);ZipEntry copy=new ZipEntry(entry.getName());copy.setTime(0);zip.putNextEntry(copy);zip.write(data);zip.closeEntry();}}return out.toByteArray();
    }
