    private byte[] word(String id,String revision)throws Exception{return mvc.perform(get("/api/drafting/{id}/documents/NTT/export.docx",id).param("revisionId",revision)).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();}
    @Test void anEditedRegisteredSctEmptyRemainsUnchangedAndSkipsLayout()throws Exception {
        byte[] original=source("SCT");Document document=xml(original);String w=NativeDocxComparison.W;Element p=(Element)document.getElementsByTagNameNS(w,"p").item(197),props=(Element)p.getElementsByTagNameNS(w,"pPr").item(0),spacing=document.createElementNS(w,"w:spacing");spacing.setAttributeNS(w,"w:line","240");spacing.setAttributeNS(w,"w:lineRule","exact");props.insertBefore(spacing,props.getElementsByTagNameNS(w,"ind").item(0));
        ByteArrayOutputStream main=new ByteArrayOutputStream();javax.xml.transform.TransformerFactory.newInstance().newTransformer().transform(new javax.xml.transform.dom.DOMSource(document),new javax.xml.transform.stream.StreamResult(main));Map<String,byte[]> entries=parts(original);entries.put("word/document.xml",main.toByteArray());ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){for(Map.Entry<String,byte[]> entry:entries.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue());zip.closeEntry();}}byte[] modified=bytes.toByteArray();assertNotEquals(DraftPdfConverter.sha256(original),DraftPdfConverter.sha256(modified));assertOpaquePartsIdentical(parts(original),parts(modified));String id=project();upload(id,"SCT",modified);
        Map<String,Object> bundle=data(mvc.perform(get("/api/drafting/{id}/templates/SCT/bindings",id)).andExpect(jsonPath("$.data.nativeLayout.status").value("skipped_unverified_source")).andExpect(jsonPath("$.data.nativeLayout.actions").isEmpty()).andReturn().getResponse().getContentAsString());assertEquals(DraftPdfConverter.sha256(modified),bundle.get("sourceSha256"));assertArrayEquals(modified,mvc.perform(get("/api/drafting/{id}/templates/SCT/source",id)).andReturn().getResponse().getContentAsByteArray());evidence("SCT-edited-empty-original.docx",modified);evidence("SCT-edited-empty-bundle.json",JsonUtils.write(bundle).getBytes(StandardCharsets.UTF_8));
    }
    /** CT_PPr sequence from the official Open-XML-SDK schema: tabs < spacing < ind/jc/rPr. */
    private static void assertSpacingOrder(Element paragraph){String w=NativeDocxComparison.W;Element props=(Element)paragraph.getElementsByTagNameNS(w,"pPr").item(0);boolean seen=false;for(Node child=props.getFirstChild();child!=null;child=child.getNextSibling())if(child instanceof Element){String name=child.getLocalName();if("spacing".equals(name)){assertFalse(seen);seen=true;}else if("tabs".equals(name))assertFalse(seen,"Spacing must follow original tabs");else if(Set.of("ind","jc","rPr").contains(name))assertTrue(seen,"Spacing must precede the original late paragraph properties");}assertTrue(seen);}
    private static Map<String,Object> patch(Map<String,Object> doc,Map<String,Object> block,String text,List<String> insert){Map<String,Object> edit=DraftBusinessRules.map("id",block.get("id"),"bindingId",block.get("bindingId"),"expectedTextHash",block.get("textHash"),"text",text);if(insert!=null)edit.put("insertAfter",insert);return DraftBusinessRules.map("revisionId",doc.get("revisionId"),"docxSha256",doc.get("docxSha256"),"blocks",Collections.singletonList(edit));}
    private static Document xml(byte[] bytes)throws Exception {try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry entry;while((entry=in.getNextEntry())!=null)if("word/document.xml".equals(entry.getName())){DocumentBuilderFactory factory=DocumentBuilderFactory.newInstance();factory.setNamespaceAware(true);factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);return factory.newDocumentBuilder().parse(new ByteArrayInputStream(in.readAllBytes()));}}throw new IllegalArgumentException("Missing native document");}
    private byte[] exportWord(String id,String key)throws Exception{return mvc.perform(get("/api/drafting/{id}/documents/{key}/export.docx",id,key)).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();}
    private static Map<String,byte[]> parts(byte[] bytes)throws Exception {Map<String,byte[]> result=new LinkedHashMap<>();try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry entry;while((entry=in.getNextEntry())!=null)result.put(entry.getName(),in.readAllBytes());}return result;}
    private static void assertOpaquePartsIdentical(Map<String,byte[]> expected,Map<String,byte[]> actual){assertEquals(expected.keySet(),actual.keySet());for(String part:expected.keySet())if(!"word/document.xml".equals(part))assertArrayEquals(expected.get(part),actual.get(part),"Opaque native part: "+part);}
    @SuppressWarnings("unchecked") private static void assertOnlyRegisteredNativeLayoutDiffers(byte[] original,byte[] baseline,byte[] actual,Map<String,Object> layout,int[] allowedEmptyOrdinals)throws Exception {
        Map<String,byte[]> a=parts(baseline),b=parts(actual);assertOpaquePartsIdentical(a,b);
        Document source=xml(original),expected=NativeDocxComparison.withoutAddedBindings(source,xml(baseline)),restored=NativeDocxComparison.withoutAddedBindings(source,xml(actual));String w=NativeDocxComparison.W;Map<String,Map<String,Object>> layoutIds=new HashMap<>();com.consense.document.DocxTemplateEditor editor=new com.consense.document.DocxTemplateEditor();com.consense.document.DocxTemplateEditor.TemplateIndex sourceIndex=editor.inspect(original),actualIndex=editor.inspect(actual);
        if(layout!=null)for(Map<String,Object> action:(List<Map<String,Object>>)layout.get("actions"))if("APPLIED".equals(action.get("status"))&&action.get("layoutId")!=null)assertNull(layoutIds.put(String.valueOf(action.get("layoutId")),action));
        int removed=0;for(Element marker:NativeDocxComparison.elements(restored,"bookmarkStart"))if(layoutIds.containsKey(marker.getAttributeNS(w,"name"))){Element p=(Element)marker.getParentNode();Map<String,Object> action=layoutIds.get(marker.getAttributeNS(w,"name"));assertEquals(0,p.getElementsByTagNameNS(w,"t").getLength());assertEquals(1,p.getElementsByTagNameNS(w,"bookmarkEnd").getLength());Element end=(Element)p.getElementsByTagNameNS(w,"bookmarkEnd").item(0);assertEquals(marker.getAttributeNS(w,"id"),end.getAttributeNS(w,"id"));assertFalse(marker.hasChildNodes());assertFalse(end.hasChildNodes());
            if("page_break_before".equals(action.get("action"))){assertEquals("body",p.getParentNode().getLocalName());assertEquals(1,p.getElementsByTagNameNS(w,"pageBreakBefore").getLength());p.getParentNode().removeChild(p);}else{
                assertEquals("compact_verified_empty_spacing",action.get("action"));com.consense.document.DocxTemplateEditor.Paragraph originalParagraph=sourceIndex.paragraph(String.valueOf(action.get("sourceId")));assertTrue(Arrays.stream(new int[]{146,147,148,149,150,153,154,198,199,200,202,203,204,205,206,207,208,209,212,213,955}).anyMatch(n->n==originalParagraph.getOrdinal()));assertEquals(sourceIndex.anchor(originalParagraph.getId()).getSha256(),action.get("sourceNodeSha256"));assertTrue(actualIndex.paragraph(String.valueOf(action.get("generatedId"))).hasCompactEmptyLayoutSpacing());assertSpacingOrder(p);Element originalP=(Element)source.getElementsByTagNameNS(w,"p").item(originalParagraph.getOrdinal()-1);assertEquals(originalP.getAttributeNS("http://schemas.microsoft.com/office/word/2010/wordml","paraId"),p.getAttributeNS("http://schemas.microsoft.com/office/word/2010/wordml","paraId"));p.removeChild(marker);p.removeChild(end);p.removeChild(p.getElementsByTagNameNS(w,"pPr").item(0));Node originalProps=originalP.getElementsByTagNameNS(w,"pPr").item(0);if(originalProps!=null)p.insertBefore(restored.importNode(originalProps,true),p.getFirstChild());assertTrue(originalP.isEqualNode(p),"Only the recorded spacing and complete added CL pair may change the original empty node");
            }removed++;}assertEquals(layoutIds.size(),removed);
        Set<String> allowedIds=new HashSet<>();for(int ordinal:allowedEmptyOrdinals){Element p=(Element)source.getElementsByTagNameNS(w,"p").item(ordinal-1);assertEquals("body",p.getParentNode().getLocalName());assertEquals(0,p.getElementsByTagNameNS(w,"t").getLength());allowedIds.add(p.getAttributeNS("http://schemas.microsoft.com/office/word/2010/wordml","paraId"));}
        Node expectedBody=expected.getElementsByTagNameNS(w,"body").item(0),actualBody=restored.getElementsByTagNameNS(w,"body").item(0),current=actualBody.getFirstChild();int reinstated=0;
        for(Node node=expectedBody.getFirstChild();node!=null;node=node.getNextSibling())if(current!=null&&node.isEqualNode(current))current=current.getNextSibling();else if(node instanceof Element&&"p".equals(node.getLocalName())&&allowedIds.contains(((Element)node).getAttributeNS("http://schemas.microsoft.com/office/word/2010/wordml","paraId"))){actualBody.insertBefore(restored.importNode(node,true),current);reinstated++;}else fail("Unregistered native content/property change: "+node.getNodeName());
        assertNull(current);assertEquals(allowedEmptyOrdinals.length,reinstated);assertTrue(expected.isEqualNode(restored),"All native fields, controls, paragraphs, tables, styles and attributes must match the baseline business output after reverting only the registered layout");
    }
    private static void assertNoBlankOrFurnitureOnly(byte[] bytes,String key)throws Exception {try(PDDocument pdf=PDDocument.load(bytes)){for(int page=1;page<=pdf.getNumberOfPages();page++){PDFTextStripper strip=new PDFTextStripper();strip.setStartPage(page);strip.setEndPage(page);String substantive=strip.getText(pdf).replaceAll("\\s+","").replace("March2020","").replaceAll("HD\\(QS\\)3C/121/[0-9/]+","").replaceAll("[-–]"+key+"/[0-9]+[-–]","").replaceAll("[^A-Za-z0-9]","");assertFalse(substantive.isEmpty(),"Unexpected blank/furniture-only physical page "+page);}}}
    private static void assertNoFooterThenTitle(byte[] bytes,String key)throws Exception {
        List<String> collisions=new ArrayList<>();try(PDDocument pdf=PDDocument.load(bytes)) {
            for(int page=1;page<=pdf.getNumberOfPages();page++) {
                final Map<Integer,List<TextPosition>> glyphLines=new TreeMap<>();PDFTextStripper strip=new PDFTextStripper(){@Override protected void processTextPosition(TextPosition position){glyphLines.computeIfAbsent(Math.round(position.getYDirAdj()*2),y->new ArrayList<>()).add(position);}};
                strip.setStartPage(page);strip.setEndPage(page);strip.getText(pdf);boolean footer=false;List<String> lines=new ArrayList<>();
                for(List<TextPosition> glyphs:glyphLines.values()){glyphs.sort(Comparator.comparing(TextPosition::getXDirAdj));StringBuilder line=new StringBuilder();for(TextPosition glyph:glyphs)line.append(glyph.getUnicode().replaceAll("\\s+",""));lines.add(line.toString());}
                for(String line:lines){if(line.matches(".*"+key+"/[0-9]+.*"))footer=true;if(footer&&("NTT".equals(key)?line.contains("NOTESTOTENDERERS"):line.contains("SPECIALCONDITIONSOFTENDER")))collisions.add("physical"+page+": "+line);}
            }
        }
        assertTrue(collisions.isEmpty(),"A registered continuation must not follow its preceding manual footer on the same physical page: "+collisions);
    }
